) as v(canonical_key, event_fingerprint, observed_at, session_id, source_message_id, raw_url, metadata)
join public.links l on l.canonical_key = v.canonical_key
on conflict (event_fingerprint) do nothing;

update public.system_counters
set counter_value = greatest(counter_value, 1156)
where counter_key = 'link_display_serial';

do $$
declare
  v_links bigint;
  v_sent bigint;
  v_unconfirmed bigint;
  v_occurrences bigint;
  v_counter bigint;
begin
  select count(*) into v_links from public.links where metadata->>'recoverySourceSha256' = '1e9c1a1aac29434ce86451055f721d92d87b92f9a088cd6f1aba26cb7d9358f0';
  select count(*) into v_sent from public.links where metadata->>'recoverySourceSha256' = '1e9c1a1aac29434ce86451055f721d92d87b92f9a088cd6f1aba26cb7d9358f0' and status = 'historically_sent';
  select count(*) into v_unconfirmed from public.links where metadata->>'recoverySourceSha256' = '1e9c1a1aac29434ce86451055f721d92d87b92f9a088cd6f1aba26cb7d9358f0' and status = 'observed_unconfirmed';
  select count(*) into v_occurrences from public.link_occurrences where metadata->>'recoverySourceSha256' = '1e9c1a1aac29434ce86451055f721d92d87b92f9a088cd6f1aba26cb7d9358f0';
  select counter_value into v_counter from public.system_counters where counter_key = 'link_display_serial';
  if v_links <> 5835 or v_sent <> 4082 or v_unconfirmed <> 1753 or v_occurrences <> 8158 or v_counter < 1156 then
    raise exception 'Recovery verification failed: links %, sent %, unconfirmed %, occurrences %, counter %', v_links, v_sent, v_unconfirmed, v_occurrences, v_counter;
  end if;
end;
$$;

